import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        PriorityQueue<Integer> heap = new PriorityQueue<>(Collections.reverseOrder());
        for (int stone : stones) {
            heap.offer(stone);
        }

        while (heap.size() > 1) {
            int y = heap.poll();
            int x = heap.poll();
            if (y != x) {
                heap.offer(y - x);
            }
        }

        return heap.isEmpty() ? 0 : heap.peek();
    }
}

import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        List<Integer> remaining = new ArrayList<>();
        for (int stone : stones) {
            remaining.add(stone);
        }

        while (remaining.size() > 1) {
            Collections.sort(remaining);
            int y = remaining.remove(remaining.size() - 1);
            int x = remaining.remove(remaining.size() - 1);
            if (y != x) {
                remaining.add(y - x);
            }
        }

        return remaining.isEmpty() ? 0 : remaining.get(0);
    }
}

class Solution {
    public int lastStoneWeight(int[] stones) {
        int max = 0;
        for (int stone : stones) {
            max = Math.max(max, stone);
        }
        int[] buckets = new int[max + 1];
        for (int stone : stones) {
            buckets[stone]++;
        }

        int current = max;
        while (true) {
            int y = takeLargest(buckets, current);
            if (y == 0) {
                return 0;
            }
            current = Math.min(current, y);
            int x = takeLargest(buckets, current);
            if (x == 0) {
                return y;
            }
            if (x != y) {
                buckets[y - x]++;
                current = Math.max(current, y - x);
            }
        }
    }

    private int takeLargest(int[] buckets, int start) {
        for (int weight = start; weight > 0; weight--) {
            if (buckets[weight] > 0) {
                buckets[weight]--;
                return weight;
            }
        }
        return 0;
    }
}

import java.util.*;

class Solution {
    public int lastStoneWeight(int[] stones) {
        TreeMap<Integer, Integer> counts = new TreeMap<>();
        int total = 0;
        for (int stone : stones) {
            counts.put(stone, counts.getOrDefault(stone, 0) + 1);
            total++;
        }

        while (total > 1) {
            int y = removeLargest(counts);
            int x = removeLargest(counts);
            total -= 2;
            if (y != x) {
                counts.put(y - x, counts.getOrDefault(y - x, 0) + 1);
                total++;
            }
        }

        return total == 0 ? 0 : counts.lastKey();
    }

    private int removeLargest(TreeMap<Integer, Integer> counts) {
        int weight = counts.lastKey();
        int count = counts.get(weight);
        if (count == 1) {
            counts.remove(weight);
        } else {
            counts.put(weight, count - 1);
        }
        return weight;
    }
}
